CREATE OR REPLACE PROCEDURE GN_DW.SERVING.USP_ASK_AGENT_POC(AGENT_NAME VARCHAR, QUESTION VARCHAR) RETURNS VARCHAR LANGUAGE SQL EXECUTE AS OWNER COMMENT='O208-B X3 PoC — 하위 Agent 1회 호출 후 답변 텍스트·사용 도구 반환(허용 = AGENT_EXECUTIVE·AGENT_MEMBER·AGENT_MARKETING) · 임시 객체' AS '
DECLARE
  fqn VARCHAR;
  body VARCHAR;
  resp VARIANT;
  ans VARCHAR;
BEGIN
  IF (UPPER(:AGENT_NAME) NOT IN ('AGENT_EXECUTIVE','AGENT_MEMBER','AGENT_MARKETING')) THEN
    RETURN 'ERROR 허용되지 않은 Agent: ' || :AGENT_NAME;
  END IF;
  fqn := 'GN_DW.SERVING.' || UPPER(:AGENT_NAME);
  body := TO_JSON(OBJECT_CONSTRUCT('messages', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT('role','user','content', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT('type','text','text', :QUESTION))))));
  resp := PARSE_JSON(SNOWFLAKE.CORTEX.DATA_AGENT_RUN(:fqn, :body));
  SELECT LISTAGG(c.value:text::STRING, '\n') INTO :ans FROM TABLE(FLATTEN(INPUT => :resp:content)) c WHERE c.value:type::STRING = 'text';
  RETURN '[' || UPPER(:AGENT_NAME) || ' 답변]\n' || COALESCE(:ans, '(텍스트 없음)');
END;
'

